"""One authored teaching sequence for reading, presenting, and further study.

The audience content and its explanation are parts of the same teaching block.
Presentation mode reads those blocks directly from the lesson DOM.
"""
from retail_ui import p,table,formula,chart,section,esc,bar_figure,scatter_figure,distribution_figure
from presentation_content import outline

def bullets(*items): return '<ul>'+''.join('<li>'+esc(item)+'</li>' for item in items)+'</ul>'
def code(text): return '<pre><code>'+esc(text)+'</code></pre>'
def teach(title,visual,explanation=''):
    paragraphs=p(*explanation) if isinstance(explanation,(list,tuple)) else p(explanation)
    return '<div class="teaching-block" data-presentation-title="'+esc(title)+'"><h3>'+esc(title)+'</h3><div class="teaching-visual">'+visual+'</div>'+('<div class="teaching-explanation">'+paragraphs+'</div>' if explanation else '')+'</div>'

DISCUSS={
 'Diagnose before cleaning':(['Repeated stores, transfers, and joined rows: which are errors?'],['Check the intended observation and key','Preserve valid repeated observations','Resolve the staffing time rule before removing rows']),
 'Choose the next investigation':(['Many tests; only the smallest p-value is reported. What next?'],['Request the primary outcome and all comparisons','Separate planned from exploratory findings','Confirm important findings with new evidence']),
 'Turn a coefficient into a sentence':(['How should the director interpret an interaction?'],['Name two store profiles','Hold other inputs fixed','Calculate both outcomes and report the difference']),
 'Choose a control by its role':(['Adjust for post-alert review effort when estimating the total effect?'],['Retain the pathway through review effort','Adjust for pre-offer common causes','Choose controls for the stated effect']),
 'Name what the estimate covers':(['Stricter matching excludes adopters. Whose effect is estimated?'],['Report the retained adopter subset','Compare included and excluded stores','Use the matched target when comparing estimates']),
 'Complete the expansion recommendation':(['What belongs beside the final DiD estimate?'],['Name the groups, periods, outcome, and trend argument','Report uncertainty and the accounting rule','Specify the next action and review criteria'])}

def ask(title,prompt,answer):
    question_points,answer_points=DISCUSS[title]
    return teach(title,bullets(*question_points)+'<details><summary>Discuss, then reveal</summary>'+outline(answer_points,'answer')+p(answer)+'</details>',prompt)
def before(c,anchor,*sections):
    at=next(i for i,x in enumerate(c['sections']) if x['id']==anchor)
    c['sections'][at:at]=sections
def diagram(title,paths):
    # Text-based paths remain selectable and readable with assistive technology.
    return '<figure class="causal-paths" role="group" aria-label="'+esc(title)+'">'+''.join('<p>'+esc(path)+'</p>' for path in paths)+'<figcaption>'+esc(title)+'</figcaption></figure>'
def num(x): return f'{x:.2f}'

def enrich(n,c,r):
    d=r['depth'];f=num
    if n==1:
        a=r['preparation']
        before(c,'read-data',section('evidence','Begin with the decision and the evidence',
          teach('The first approval is for the data',bullets('Decision: should the chain test replenishment alerts?','Evidence needed: a comparable measure of shelf availability.','Deliverable: a documented baseline that another analyst can reproduce.'),
            'The director’s question gives the preparation work a purpose. Each choice—what to collect, whom to include, how to combine records—changes the evidence available for the spending decision. This lesson follows that chain from a source record to a review table.')+
          teach('What you should be able to do',bullets('Explain where a dataset came from and whom it represents.','Choose observations, variables, measurement scales, and keys.','Reshape, join, clean, aggregate, and validate the records.','Explain the business measure and reproduce the handover.'),
            'Treat these skills as stages of one management deliverable. By the end of the lesson, another analyst should be able to reconstruct the stockout baseline and explain why its rows, denominator, and repair decisions fit the director’s question.')+
          teach('Different sources answer different operating questions',table(['Source','Retail use','Collection choice'],[
            ['Systems and APIs','Sales, orders, delivery logs','What event triggers a record?'],['Web records','Competitor prices and availability','Which products and times are visible?'],['Administrative records','Store registry and staffing','How are openings and changes recorded?'],['Surveys and interviews','Staff explanations of replenishment','Who answers, and how is the question asked?'],['Experiments','Test an alert policy','Who receives the offer, and when?']],'Choose the source to fit the decision'),
            'A transaction records an event the system was designed to capture. A survey records an answer to a question. An experiment changes an operating rule and measures what follows. Combine these sources deliberately: agreeing on a source is part of defining the business question, not simply a file-format choice.')+
          teach('Six questions make quality concrete',table(['Question','Apply it to shelf availability'],[
            ['Meaning','Does a stockout mean unavailable on the shelf or absent from the warehouse?'],['Validity','Does this measure the customer-facing availability we want to improve?'],['Reliability','Would two reviewers applying the rule obtain similar counts?'],['Comparability','Are products, days, and counting rules consistent across stores?'],['Coverage','Which stores, products, and trading days are represented?'],['Selection','Are the stores that fail to report systematically different?']],'Agree the measurement protocol'),
            'Use these questions to assign work. Operations defines “unavailable”; the data team checks coverage; reviewers reconcile disagreements. A polished chart becomes useful only after the underlying measurement agreement is clear. This is the practical meaning of “garbage in, garbage out.”')))
        before(c,'calculate',section('coverage','Decide which business the file describes',
          teach('Population, sample, and reporting frame',bullets('Population: the stores and periods covered by the management question.','Frame: the list from which observations can be collected.','Sample: the observations actually selected and received.'),
            'For the baseline, the target is all 150 stores over eight weeks. That implies 1,200 expected store-week keys. The fixed basket contains 20 monitored products; the measure describes that basket. Lesson 3 later selects 30 stores for a fresh audit, which introduces a sampling question rather than changing the baseline definition.')+
          teach('More rows cannot repair a missing part of the business',bullets('Coverage: compare the store list with the operating registry.','Nonresponse: compare received and scheduled reports.','Benchmark: compare location and delivery-time composition.','Random sampling: select from the intended frame with known chances.'),
            'Imagine that only stores with reliable scanners send a weekly report. Repeatedly collecting their data adds rows without adding the missing stores. The remedy is to improve collection or define the covered population clearly. For an audit, random selection addresses the selection stage; following up selected stores addresses nonresponse.')+
          teach('The four Vs become operating requirements',table(['Dimension','Retail implication'],[
            ['Volume','More products and stores require efficient storage and checking.'],['Velocity','Alerts need information before the replenishment decision.'],['Variety','Join structured counts with logs, text reports, and supplier records.'],['Veracity','Keep definitions, source checks, and an audit trail consistent.']],'Plan for scale'),
            'Large datasets are valuable when they make the decision more timely or more informative. Start with what the extra data will change, then weigh collection, storage, access, and review costs. Obtain the right permissions and collect only the information needed for the operating purpose.')),
          section('structure','Make the table match the question',
          teach('Three structures, one continuing business',table(['Structure','One row','Question'],[
            ['Cross-sectional','One store at a specified time','Which stores differ?'],['Time series','One chain-wide week','How does the chain change over time?'],['Panel','One store in one week','How do the same stores change?']],'Recognize the observation structure'),
            'A table has observations in rows and variables in columns. Our operating file is a panel. Aggregating across stores produces a chain time series; selecting one week produces a cross-section. These are different views of the same records, each suited to a different question.')+
          teach('Measurement scales determine useful arithmetic',table(['Scale','Retail example','Useful operation'],[
            ['Nominal','Store ID or location category','Counts and group comparisons'],['Ordinal','Low, medium, high review priority','Ordering; category shares'],['Interval','A temperature measured in °C','Differences; zero is not absence of heat'],['Ratio','Stockout counts or delivery duration','Differences and meaningful ratios']],'Interpret the values before calculating'),
            'A numeric label is not necessarily a quantity: averaging store IDs has no business meaning. Priority labels have an order, but the distance between “low” and “medium” need not equal the distance to “high.” A count has a genuine zero. Temperature and priority are illustrations of measurement scales, not additional fields in the stockout file.')+
          teach('Choose a practical storage format',table(['Format','Use'],[
            ['CSV or TSV','Exchange a plain table; document delimiter, encoding, and missing-value codes.'],['Spreadsheet','Inspect tables and maintain a small data dictionary.'],['JSON or XML','Represent nested records returned by systems or APIs.'],['Parquet','Store large typed tables efficiently in columns.']],'Formats serve the same documented variables'),
            'The file extension does not tell you the observation unit or what a blank means. Preserve a source description and a variable dictionary beside the data. Record collector, purpose, dates, field definitions, units, category codes, allowed ranges, and transformations.')+
          teach('Inspect before filtering',code("import pandas as pd\nraw = pd.read_csv('raw-baseline.csv')\nraw.head()\nraw.shape\nraw.dtypes\nraw.isna().sum()"),
            'A DataFrame is the table; a Series is one column. head shows example rows, shape reports rows and columns, dtypes shows storage types, and isna counts missing values. Download the CSV from Data & labs for this loading example. The self-contained notebook creates the identical input in its shared setup.')+
          teach('Select columns and rows for explicit reasons',code("working = raw[['store_id', 'week', 'exposure', 'stockout_days']]\nfirst_weeks = working.loc[working['week'] <= 2]\nworking.iloc[:3]"),
            'A list of names selects columns. loc applies a row rule using labels or a condition; iloc selects by position. Record the before-and-after dimensions when restricting a sample. For categories, value_counts(dropna=False) shows missing labels as well as known groups. Text filters distinguish “Urban” from “urban ” until a documented coding rule reconciles them.')+
          teach('A tidy table has an explicit key',bullets('One variable per column; one observation per row.','Keep different observation types in related tables.','Store table key: store_id.','Weekly table key: store_id + week.'),
            'Identifiers should be present, stable, and unique at the chosen level. Repeated store IDs are expected in a weekly panel. Repeated store-week keys need investigation. Keep an entity crosswalk when two systems use different names for the same store; do not guess that similar names must identify the same location.')+
          teach('Test the proposed identifier',code("key = ['store_id', 'week']\nmissing_keys = raw[key].isna().any(axis=1)\nduplicate_keys = raw.duplicated(key, keep=False)\nraw.loc[missing_keys | duplicate_keys]"),
            'Inspect duplicate-key groups before removing rows. Identical repeated exports can be deduplicated; conflicting counts require a source decision. This export contains known repeated records, and the repair ledger supplies the counts for the flagged observations.')))
        before(c,'interpret',section('reshape','Show the same observations in a useful layout',
          teach('Long format keeps the observation in a row',table(['Store','Week','Stockout days','Exposure'],[[x['store_id'],x['week'],x['stockout_days'],x['exposure']] for x in a['long']],'Two stores, two weeks'),
            'The store-week key is visible in long form. Adding another week means adding rows. This layout is convenient for joining attributes, grouping, plotting time, and fitting the models later in the course.')+
          teach('Wide format makes a small review table',table(['Store']+a['wide_columns'],[[x['store_id']]+[x[k] for k in a['wide_columns']] for x in a['wide']],'The same four observations in wide form'),
            'Wide form places weeks across columns, which can help a manager compare adjacent periods. The information has not changed. Column names now combine a variable with a week, so return to a long structure when the analysis needs one store-week per row.')+
          teach('Set the key, unstack the week, name the columns',code("small = clean.query(\"store_id in ['S001','S002'] and week <= 2\")\nwide = small.set_index(['store_id','week'])[['stockout_days','exposure']]\nwide = wide.unstack('week')\nwide.columns = [f'{variable}_{week}' for variable, week in wide.columns]"),
            'The two column levels after unstack are variable and week. The naming rule makes both visible, for example stockout_days_2. For a one-variable wide table, melt moves week columns back into rows. Validate row keys and totals after either transformation; reshaping should preserve the measured information.')),
          section('relationships','Join tables without changing what a row means',
          teach('Choose the relationship before choosing the command',table(['Relationship','Example','Expected result'],[
            ['One-to-one','Store profile + store contact record','One row per store'],['Many-to-one','Weekly records + store profile','One row per store-week'],['One-to-many','One store + its weekly records','Several rows per store'],['Many-to-many','Weekly records + multiple staffing spells','Candidate pairs; apply the time rule']],'Keys determine the join'),
            'A foreign key links a row to a record in another table. A left join preserves the weekly file while bringing in store attributes. An inner join retains only matching keys. Review unmatched records before choosing whether the analytical population should shrink.')+
          teach('Make a many-to-one join prove its claim',code("stores = world()['stores'][['store_id','lead_days','urban']]\njoined = clean.merge(stores, on='store_id', how='left',\n    validate='many_to_one', indicator=True)\nassert len(joined) == len(clean)\nassert joined['_merge'].eq('both').all()"),
            f"The join retains {a['joined_rows']:,} store-weeks. validate checks uniqueness on the store side; indicator reveals unmatched rows. Together with the row-count check, these tests prevent a duplicated store profile from silently multiplying the weekly observations.")+
          teach('Responsibility also has a time key',table(['Store','Manager','First week','Last week'],[[x[k] for k in ['store_id','manager_id','start_week','end_week']] for x in a['assignments']],'Illustrative staffing ledger for two case stores'),
            'This small staffing exercise adds an explicit assignment period. S001 changes manager after week 4. Joining only on store_id produces a candidate row for each possible manager. Retain the candidate whose assignment covers the observation week. The exercise ledger does not change the course’s stockout outcomes.')+
          teach('Use the assignment dates, then recheck uniqueness',table(['Store','Week','Responsible manager','Stockout days'],[[x[k] for k in ['store_id','week','manager_id','stockout_days']] for x in a['assigned_sample']],'Responsibility around the handover')+
            formula(f"{a['assignment_candidates']} candidate pairs → {a['assignment_rows']} valid store-week assignments"),
            'A manager can work at several stores or in several periods, so manager_id alone is not a unique staffing-spell key. After the time condition, every included store-week should have exactly one responsible manager. Record gaps or overlapping assignments for review.')+
          teach('An event and an observation need not be the same thing',table(['Transfer','Week','Store','Direction','Signed units'],[[x[k] for k in ['transfer_id','week','store_id','direction','signed_units']] for x in a['perspectives']],'Illustrative stock-transfer ledger, viewed by store'),
            'Two transfers create four valid store-perspective rows: one outgoing and one incoming for each event. The key is transfer_id plus store_id. Removing the second occurrence of a transfer ID would destroy a valid observation. Signed units sum to zero across the chain, providing an additional reconciliation check.')),
          section('aggregation','Build a review table at the level of the decision',
          teach('Grouping changes the observation unit',code("reports = pd.DataFrame(preparation_examples()['reports'])\nsummary = reports.groupby('store_id').agg(\n    weeks=('week','size'), stockouts=('stockout_days','sum'),\n    exposure=('exposure','sum'))\nsummary['rate'] = 100 * summary.stockouts / summary.exposure"),
            'This demonstration deliberately takes incomplete submissions from six stores. It leaves the full baseline intact. groupby collects each store’s records; named aggregation counts reporting weeks and adds stockouts and exposure. The output has one row per store, so its key and interpretation have changed.')+
          teach('Show the amount of evidence beside the ranking',table(['Store','Weeks received','Stockouts','Exposure','Rate (%)'],[[x['store_id'],x['weeks'],x['stockouts'],x['exposure'],f(x['rate'])] for x in a['summary']],'Incomplete-submission exercise, sorted from lower to higher stockout rate'),
            'A rate based on one week can move sharply with that week’s events. A review rule requiring at least six weeks makes the reporting requirement explicit. It changes eligibility, so name the resulting shortlist as “stores with at least six reported weeks,” rather than calling it the best stores in the chain.')+
          teach('Apply the eligibility rule before plotting',code("eligible = summary.loc[summary['weeks'] >= 6]\nranked = eligible.sort_values('rate')\nranked[['weeks','rate']]"),
            'For a horizontal bar chart, put the store labels on one axis and the stockout rate on the other, using a shared zero and meaningful units. The chart should describe observed service performance. Delivery conditions, product mix, and the length of observation help explain that performance; later lessons compare those conditions directly.')))
        before(c,'act',section('workflow','Hand over a reproducible piece of evidence',
          teach('Preserve, profile, define, clean, validate, document',bullets('Preserve the raw export and its collection notes.','Profile types, missing values, ranges, and category counts.','Define scope, observation, keys, and business rules.','Reconcile values and relationships; record each decision.','Validate keys, counts, ranges, join coverage, and totals.'),
            'Deletion and imputation are analytical choices. Restricting to complete records changes who remains; filling a missing count adds a value under an explicit rule or model. In this case the ledger lets us recover flagged counts. When recovery is impossible, compare reasonable alternatives and report how the choice changes the decision measure.')+
          teach('Give the project a readable structure',code('retail-analysis/\n  README.txt\n  raw/        # original exports and variable dictionary\n  clean/      # reconciled tables and repair log\n  analysis/   # scripts, figures, and decision memo'),
            'Use predictable names such as 2026-11-09_store-week_baseline.csv, stable lower-case field names, and zero-padded sequence numbers when order matters. Separate input paths from output paths. A colleague should be able to find the collection rules and run the pipeline without guessing which file is authoritative.')+
          teach('Use AI to accelerate work that can be checked',bullets('Ask for code that implements a stated business rule.','Inspect the changed rows and reconcile before-and-after totals.','Keep the original inputs and an executable audit trail.','Have a person approve definitions, exceptions, and the decision.'),
            'AI can suggest a reshape or a join quickly. The analyst still decides what counts as a stockout, which two names refer to the same store, and which staffing period applies. Reviewing these choices is part of the work, not a final decorative check. No fixed percentage of project time is assumed here.')+
          ask('Diagnose before cleaning','A store appears eight times, a transfer appears twice, and a staffing join doubles the row count. Which records should be removed?',
            'Start from the observation definition. Eight store-week rows can be valid; two transfer-perspective rows can be valid. The staffing join needs its period condition and a uniqueness check. Remove only verified repeated records, not every repeated identifier.')))
        c['code'] += "\n\n# Reshape and validate the store context\nsmall = clean.query(\"store_id in ['S001','S002'] and week<=2\")\nwide = small.set_index(['store_id','week'])[['stockout_days','exposure']].unstack('week')\nassert wide.shape == (2,4)\nstores = world()['stores'][['store_id','lead_days','urban']]\njoined = clean.merge(stores,on='store_id',how='left',validate='many_to_one',indicator=True)\nassert len(joined)==1200 and joined['_merge'].eq('both').all()\n\n# Follow assignment periods rather than merging on names alone\nexamples = preparation_examples()\nassignments = pd.DataFrame(examples['assignments'])\nweekly = clean.query(\"store_id in ['S001','S002']\")\npairs = weekly.merge(assignments,on='store_id',validate='many_to_many')\nassigned = pairs[pairs.week.between(pairs.start_week,pairs.end_week)]\nassert len(assigned)==16 and not assigned.duplicated(['store_id','week']).any()\n\n# Aggregate an explicitly incomplete teaching extract\nreports = pd.DataFrame(examples['reports'])\nsummary = reports.groupby('store_id').agg(weeks=('week','size'),stockouts=('stockout_days','sum'),exposure=('exposure','sum'))\nsummary['rate'] = 100*summary.stockouts/summary.exposure\neligible = summary.query('weeks>=6').sort_values('rate')\nassert len(eligible)==4\n"
        c['method']='Data origins, quality, organization, and preparation'
        c['technical'][3]='Reproduce the wide table, the validated store join, the period-specific staffing join, and the incomplete-submission ranking. Change one eligibility rule and record which stores enter or leave. Preserve totals when reshaping and verify the observation key after every join.'
    from curriculum_map import coverage_html
    c['coverage']=coverage_html(n)
    return add_later_lessons(n,c,r)

def add_later_lessons(n,c,r):
    d=r['depth'];f=num
    if n==2:
        before(c,'read-data',section('explore','Decide what the first inspection should reveal',
          teach('Explore before committing to one summary',bullets('Check meaning, scale, missingness, and unusual values.','Locate the centre and describe the spread.','Look for asymmetry, clusters, and extreme observations.','Compare groups and investigate relationships.'),
            'Exploratory data analysis combines numerical summaries with graphics. The director needs to know whether a typical store represents most of the chain or hides a small group with a very different operating burden. A visual pattern suggests a question to investigate; it is not yet a policy evaluation.')+
          teach('Choose a display for the question',table(['Question','Display'],[
            ['How is a numerical variable distributed?','Histogram, boxplot, or density plot'],['How do groups differ?','Common-scale histograms, grouped boxplots, or a summary table'],['How do two numerical variables move together?','Scatterplot or binned scatterplot'],['How does composition differ?','Within-group percentages and a 100% stacked bar chart']],'Let the question choose the graph'),
            'A useful graph identifies the measure, units, observations, and comparison. A useful table identifies the rows, columns, denominator, and scope. Use a chart to show a pattern and a table when exact values matter. Labels, consistent scales, and a visible source period do more work than decoration.')))
        before(c,'calculate',section('distributions','Read the full distribution of store performance',
          teach('A histogram counts stores inside intervals',bar_figure(d['histograms'][1]['bins'],'Distribution of baseline stockout rates')+table(['Rate interval (%)','Stores'],[[f"{b['low']:g} to <{b['high']:g}",b['count']] for b in d['histograms'][1]['bins'] if b['count']],'Baseline histogram counts, width 4 percentage points'),
            'The horizontal axis is the stockout rate and the vertical axis is a count of stores. Bin boundaries determine which values are combined. Narrow bins show more local detail; wide bins produce a smoother summary. Compare the width-2 and width-4 versions in the lab before deciding that a small bump is an important business segment.')+
          teach('Location and spread answer different questions',table(['Statistic','Baseline value','Interpretation'],[
            ['Mean',f(r['mean']),'Arithmetic average'],['Median',f(r['median']),'Middle store'],['Sample standard deviation',f(d['sd']),'Spread in percentage points'],['Interquartile range',f(d['iqr']),'Width of the middle half'],['Minimum to maximum',f(d['minimum'])+' to '+f(d['maximum']),'Full observed range']],'Keep centre and variation together'),
            'The mean uses every value and moves with extremes. The median depends on order. Variance averages squared deviations using n−1 in the sample formula; its square root is the standard deviation. The interquartile range uses the 25th and 75th percentiles. These summaries complement one another rather than competing to be the single correct statistic.')+
          teach('Follow the arithmetic behind the spread',formula('Mean = Σxᵢ / n; sample variance = Σ(xᵢ − mean)² / (n − 1)')+formula('Standard deviation = √variance; IQR = Q₃ − Q₁'),
            f"For the 150 store averages, sample variance is {f(d['variance'])} squared percentage points and standard deviation is {f(d['sd'])} points. Squaring gives large deviations more influence. State the original units when interpreting the square root.")+
          teach('Read a boxplot from the centre outward',bullets('The line marks the median.','The box runs from Q₁ to Q₃.','A common rule extends whiskers to observations within 1.5 × IQR.','Values beyond those fences are shown individually.'),
            f"The corresponding fences are {f(d['low_fence'])}% and {f(d['high_fence'])}%; {d['outliers']} store averages fall beyond them. A flagged point deserves investigation, not automatic deletion. A violin adds an estimated density shape; it depends on smoothing, so retain the sample size and observed range.")+
          teach('Compare the quartiles with the smoothed shape',distribution_figure(d['density'],r['q1'],r['median'],r['q3'],d['minimum'],d['maximum']),
            'The upper shape is a Gaussian kernel density estimate using the default Scott bandwidth rule. The lower display marks the quartiles, median, and observed range. Its range line is a deliberately labelled alternative to the 1.5-IQR whisker convention. Both displays summarize the same store averages; the density shows estimated shape while the box emphasizes location and spread.')+
          teach('Distinguish skewness from tail weight',table(['Shape measure','Calculated value','What it describes'],[
            ['Sample skewness',f(d['skewness']),'Asymmetry around the centre'],['Excess kurtosis',f(d['excess_kurtosis']),'Tail weight relative to the normal benchmark']],'Two aspects of distribution shape'),
            'A long right tail can make the mean exceed the median. Kurtosis does not simply measure how tall the centre looks. Use the graph, the summary table, and the underlying rows together, especially when there are few extreme stores.')+
          teach('Use the same scale for a fair comparison',bullets('Use common bin boundaries for both delivery groups.','Show percentages or density when group counts differ.','Keep axis ranges and the observation period fixed.','State any filtering rule before interpreting the difference.'),
            'A density curve is a smoothed distribution estimate whose area is one. Histogram counts describe numbers of stores; density describes relative concentration. Filtering to a particular location or delivery segment changes the population represented, so retain its denominator in the comparison.')))
        before(c,'act',section('association','Connect composition and association to the review decision',
          teach('Compare composition within each group',table(['Delivery group','Stores','At/below 10%','10–15%','Above 15%'],[[g['group'],g['n']]+[f(v)+'%' for v in g['percent']] for g in d['composition']],'Within-group stockout bands'),
            'The percentages in each row sum to 100. A 100% stacked bar would show the same composition, using a consistent order from lower to higher stockout burden. Ordered categories preserve that meaning when tables are reshaped or plotted.')+
          teach('Conditional means answer a narrower question',formula('E[stockout rate | delivery group] = average rate within that group'),
            'The overall mean describes the chain. A conditional mean describes stores sharing a named characteristic. Description asks what those stores look like; prediction asks what we expect for another observation; a causal question asks what would change if management altered a policy. The same association can support the first two without identifying the third.')+
          teach('Use bins to make a broad relationship visible',scatter_figure([x['demand'] for x in d['bins']],[x['rate'] for x in d['bins']],'Binned demand–stockout relationship','Mean demand index','Mean stockout rate (%)',unit='demand bin')+table(['Mean demand index','Mean baseline rate (%)','Stores'],[[f(x['demand']),f(x['rate']),x['n']] for x in d['bins']],'Five quantile bins of baseline demand'),
            'Sort stores by baseline demand, divide them into five groups with similar counts, and plot each group’s mean demand against its mean rate. Quantile bins need not have equal widths. The binned points summarize the relationship, while an individual-store scatterplot shows the variation hidden by averaging.')+
          teach('Covariance and correlation quantify co-movement',formula('Correlation = covariance(X,Y) / [SD(X) × SD(Y)]')+
            bullets(f"Demand–stockout covariance: {f(d['covariance'])}",f"Correlation: {f(d['correlation'])}"),
            'Covariance retains the units of both variables. Correlation standardizes them and lies between −1 and 1. It measures linear association; a value near zero can coexist with a nonlinear relationship. Compare subgroup correlations with their sample sizes, and use the operating process to decide what the relationship might mean.')))
    if n==3:
        before(c,'calculate',section('sampling-variation','Separate variation in stores from variation in estimates',
          teach('A statistic changes when the sample changes',bullets('Parameter: the population quantity the decision concerns.','Estimate: the number calculated from this sample.','Sampling distribution: the estimates we would obtain over repeated samples.'),
            'One audit gives a point estimate. Repeating the selection and measurement process would produce other estimates. Standard deviation describes differences among store rates; standard error describes the precision of their average. Keeping these two quantities separate prevents a precise mean from being mistaken for uniform store performance.')+
          teach('Why sample size helps precision',formula('SE(mean) = sample SD / √n'),
            'With a comparable sampling process and variability, quadrupling the number of stores roughly halves the standard error. The law of large numbers concerns averages stabilizing as information accumulates. The central limit theorem explains why many sample averages become approximately normal under suitable conditions; the observations themselves need not be normally distributed.')+
          teach('A proportion needs its own uncertainty calculation',bullets(f"Above target: {d['proportion']['successes']} of {d['proportion']['n']} audited stores",f"Estimated share: {f(100*d['proportion']['value'])}%",f"Wilson 95% interval: {f(100*d['proportion']['low'])}%–{f(100*d['proportion']['high'])}%"),
            'This statistic describes the share of stores missing the target, not their average stockout rate. A store is counted once as above or below the threshold. The elementary proportion standard error is √[p̂(1−p̂)/n]; a Wilson interval behaves better near the ends of the zero-to-one range.')))
        before(c,'act',section('resampling','Use the observed stores to rehearse repetition',
          teach('Bootstrap the unit that was sampled',bullets('Draw 30 store rates with replacement from the 30 observed rates.','Calculate the mean for that draw.','Repeat 2,000 times and inspect the distribution of means.','Use its spread to estimate uncertainty.'),
            'Sampling with replacement allows the same observed store to appear more than once in a bootstrap sample. We resample stores because the audit selected stores. Resampling product-days independently would describe a different sampling process.')+
          teach('Compare analytical and bootstrap uncertainty',table(['Procedure','Standard error','95% interval'],[
            ['Store-level t interval',f(r['se']),f(r['low'])+' to '+f(r['high'])],['Bootstrap percentile',f(d['bootstrap_se']),f(d['bootstrap_low'])+' to '+f(d['bootstrap_high'])]],'Same audit, two uncertainty calculations'),
            'The percentile interval uses the 2.5th and 97.5th percentiles of the bootstrap means. Increasing the number of bootstrap repetitions smooths the simulation; it does not create new stores or remove a collection problem. A precise estimate still applies to its specified population, period, and measurement process.')+
          teach('Subsampling answers a different repetition question',bullets('Select 15 distinct stores without replacement',f"SD of subsample means: {f(d['subsample_sd'])} points",'Interpret the spread for this smaller sample size'),
            'The subsample is smaller and excludes replacement. Its raw spread is not automatically the standard error of the full 30-store estimator. Specify sample size and replacement when describing a resampling procedure. The lab calculates both so their different purposes are visible.')),
          section('testing','Turn the service target into a testable claim',
          teach('Write the claim before inspecting the p-value',formula('H₀: mean stockout rate = 10%; H₁: mean stockout rate > 10%'),
            'The one-sided alternative matches the director’s concern that service is worse than the target. A two-sided alternative asks whether the mean differs in either direction. Choose the direction and significance level before seeing the result. A composite alternative contains a range of possible values; the null value here is specific.')+
          teach('Measure distance from the null in standard-error units',formula(f"t = ({f(r['mean'])} − 10) / {f(r['se'])} = {f(d['t_statistic'])}")+
            bullets(f"One-sided p-value: {d['p_one_sided']:.4f}",f"Two-sided p-value: {d['p_two_sided']:.4f}"),
            'The p-value is the probability, under the stated null model, of a result at least as extreme in the specified direction. It is not the probability that the null hypothesis is true. A critical-value rule and a p-value rule make the same decision when they use the same test and significance level.')+
          teach('Treat testing as an error-and-cost decision',table(['Reality and decision','Name','Retail consequence'],[
            ['Reject a true null','Type I error','Investigate a gap that is sampling variation'],['Fail to reject a false null','Type II error','Miss an operating problem'],['Reject when a specified alternative is true','Power','Detect an improvement or shortfall of practical size']],'Define the decision rule in advance'),
            'Lowering the false-positive threshold usually makes detection harder at a fixed sample size. Power depends on the effect size, variability, number of independent units, and chosen threshold. A small p-value does not tell us whether a service difference is large enough to cover intervention costs.')+
          teach('Match the test to the relationship between rows',table(['Question','Data structure','Procedure'],[
            ['Does the mean exceed 10%?','One sampled store rate per store','One-sample t-test'],['Do audit and system readings differ?','Two readings of each sampled store','Paired t-test on within-store differences'],['Do urban and other stores differ?','Different stores in two groups','Welch independent-groups t-test']],'The pairing is a design fact'),
            'Do not discard the matching when two measurements concern the same store. Conversely, two groups containing different stores should not be paired merely because they have equal sizes. The independent-groups comparison is descriptive; the groups were not randomized.')+
          teach('Check a paired difference directly',bullets(f"Audit − system: {f(d['paired']['mean'])} points",f"95% interval: {f(d['paired']['low'])}–{f(d['paired']['high'])} points",f"Two-sided p-value: {d['paired']['p']:.4f}"),
            'Join the week-16 audit to the week-16 system rate by store ID, subtract within each store, and test the mean difference against zero. Both readings concern the same monitoring basket. The result evaluates agreement between measurements rather than the causal effect of alerts, which have not yet begun.')+
          ask('Choose the next investigation','A team tries many outcomes and thresholds, then reports only the smallest p-value. What should the director ask for?',
            'Ask for the planned primary outcome and the complete set of comparisons, distinguish planned from exploratory findings, and confirm important results with new evidence. Multiple testing raises the chance of finding an apparently unusual result by chance.')))
    if n==4:
        before(c,'calculate',section('from-bins','Move from a group comparison to a fitted relationship',
          teach('Three increasingly detailed predictions',table(['Rule','Prediction for a store'],[
            ['Overall mean','The same rate for every store'],['Delivery-bin means','The mean for stores in its delivery group'],['Fitted line','Intercept + slope × delivery days']],'Choose the detail that serves the question'),
            'A binned scatterplot places one mean outcome at each group’s mean predictor. More bins reveal more local variation but leave fewer observations behind each mean. A line imposes a compact relationship that can be evaluated for a specified delivery time.')+
          teach('OLS chooses a line by squared vertical misses',formula('Choose intercept a and slope b to minimize Σ[yᵢ − (a + bxᵢ)]²'),
            'The residual is actual rate minus fitted rate, measured vertically on a scatterplot. Ordinary least squares gives larger misses greater weight by squaring them. With an intercept, the fitted residuals sum to zero, and the line passes through the sample means.')+
          teach('Recover the slope from covariance',formula(f"Slope = covariance(delivery days, rate) / variance(delivery days) = {f(d['slope_covariance'])}"),
            'The intercept is the mean outcome minus the slope times the mean predictor. These closed-form formulas describe simple regression with an intercept. A one-day slope is a difference in percentage points here, because the outcome itself is a percentage.')))
        before(c,'act',section('fit','Account for what the fitted line represents',
          teach('Partition the variation around the mean',table(['Quantity','Sum of squares'],[
            ['Total: Σ(y − mean y)²',f(d['sst'])],['Explained: Σ(fitted − mean y)²',f(d['ssr'])],['Residual: Σ(y − fitted)²',f(d['sse'])]],'OLS variation decomposition')+
            formula('Total = explained + residual; R² = 1 − residual / total'),
            f"R² is {f(d['r_squared'])}. It describes how much of this sample’s variation is represented by the fitted relationship. It does not state the causal importance of delivery time or the accuracy of forecasts for later weeks.")+
          teach('Keep goodness of fit in business units',formula(f"MSE = SSE / n = {f(d['mse'])}; RMSE = √MSE = {f(d['rmse'])} points"),
            'RMSE is easier to interpret than squared error because it returns to the outcome’s units. Here the divisor n describes average squared fitting error; a residual-variance estimate for inference uses the residual degrees of freedom instead. Read a model report in order: sample, outcome units, coefficients, uncertainty, then fit.')),
          section('functional-form','Let the operating relationship have a different shape',
          teach('Four forms make four different claims',table(['Specification','Interpretation of slope b'],[
            ['Y = a + bX','One unit of X corresponds to b units of Y'],['ln Y = a + bX','One unit of X corresponds to about 100b% in Y'],['Y = a + b ln X','A 1% increase in X corresponds to about b/100 units of Y'],['ln Y = a + b ln X','A 1% increase in X corresponds to about b% in Y']],'Levels, logarithms, and business interpretation'),
            'A log transformation requires positive values. For a log outcome, an exact one-unit change in X corresponds to 100[exp(b)−1] percent. For finite proportional changes in X, use the change in its logarithm. Inspect the observed range and the relationship before choosing a form.')+
          teach('Compare the forms on the same outcome scale',table(['Form','Slope','Training RMSE on rate scale'],[[x['model'],f(x['slope']),f(x['rmse_original'])] for x in d['forms']],'Same stores and delivery predictor, different specifications'),
            'Models whose dependent variables are rate and log rate do not have directly comparable residual sums of squares on their fitted scales. The table evaluates predictions back in percentage points. Log-outcome predictions use a residual smearing factor when returning to the mean rate scale. Later validation asks how well a chosen procedure works on new observations.')+
          teach('Polynomial terms describe curvature jointly',table(['Model','Coefficients including intercept','Training RMSE'],[[x['model'],x['parameters'],f(x['rmse'])] for x in d['nonlinear']],'Flexible delivery-time specifications'),
            'A quadratic adds X²; a cubic adds X³. Interpret the predicted curve or its derivative, not the highest-order coefficient alone. Delivery time takes only four values in this case, so a cubic is already very flexible relative to the support. More training fit is a reason to validate, not a reason to extrapolate far beyond observed stores.')+
          teach('A spline lets the slope change at a named point',formula('Rate = a + b × lead + c × max(lead − 3.5, 0)'),
            'Below 3.5 days the slope is b; above it the slope is b+c. The curve stays continuous at the knot. The knot is a modelling choice between the observed three- and four-day groups, not evidence that a physical discontinuity occurs there.')+
          teach('A local smoother can reveal shape without one global line',table(['Baseline demand index','Locally fitted rate (%)'],[[f(x['demand']),f(x['rate'])] for x in d['local']],'Local linear smoothing across the demand range'),
            'For each displayed demand value, fit a small weighted line using nearby stores, with closer observations receiving more weight. This LOWESS-style demonstration uses a 60% neighborhood and no robustness iterations. The bandwidth controls smoothness. It is an exploratory description of the same stores; the lab exposes its weighting rule.')))
        c['appendix_extra']=section_html('regression-details','Derive and reproduce the model comparisons',
          formula('b = Σ(xᵢ − x̄)(yᵢ − ȳ) / Σ(xᵢ − x̄)²; a = ȳ − bx̄')+
          formula('Quadratic marginal association = b₁ + 2b₂X; cubic adds 3b₃X²')+
          p('The variation identity applies to in-sample OLS with an intercept. The local smoother uses a tricube distance weight inside each neighborhood. Log predictions are retransformed using exp(predicted log outcome) multiplied by the mean of exp(training residual). This separates prediction on a log scale from prediction of the arithmetic mean.')+
          code("stores = world()['stores']\nx = stores.lead_days.to_numpy()\ny = stores.baseline_rate.to_numpy()\nX = np.column_stack([np.ones(len(x)), x])\nbeta, covariance, residual = fit_ols(X, y)\nsst = ((y - y.mean()) ** 2).sum()\nsse = (residual ** 2).sum()\nr_squared = 1 - sse / sst"))
    if n==5:
        before(c,'read-data',section('regression-uncertainty','Ask how precisely the fitted relationships are known',
          teach('A coefficient estimate comes with sampling uncertainty',table(['Term','Estimate','Robust SE','95% interval'],[[x['term'],f(x['value']),f(x['se']),f(x['low'])+' to '+f(x['high'])] for x in d['coefficients']],'Multiple-regression coefficient report'),
            'The coefficients describe the specified model for the store population represented by the baseline. Robust standard errors allow the residual variance to differ across stores. For a single coefficient, a large-sample interval is estimate ±1.96×SE, and a zero-slope test compares the estimate with zero in standard-error units. Keep 95% intervals paired with two-sided 5% tests.')+
          teach('The mean prediction and a new store are different targets',table(['Lead days','Fitted mean','95% mean interval','95% individual interval'],[[x['lead'],f(x['mean']),f(x['mean_low'])+' to '+f(x['mean_high']),f(x['prediction_low'])+' to '+f(x['prediction_high'])] for x in d['intervals']],'Simple-model interval demonstration'),
            'A confidence interval concerns the average outcome at the specified delivery time. An individual prediction interval adds the variation of a new store around that mean, so it is wider. This teaching calculation uses the simple model with constant residual variance; the coefficient table above uses robust uncertainty for the richer model.')))
        before(c,'interpret',section('controls','Explain why adding a variable changes a coefficient',
          teach('Omitted-variable bias has two ingredients',formula('Short-model slope = long-model slope + omitted-variable effect × sorting slope'),
            'An omitted factor can change a fitted slope when it is associated with both the included predictor and the outcome. The sorting slope comes from regressing the omitted factor on the included predictor. This algebra describes a change between regressions; a causal interpretation additionally depends on the business assignment process.')+
          teach('Check the identity on the retail stores',table(['Component','Value'],[
            ['Lead slope without location',f(d['ovb']['short'])],['Lead slope with location',f(d['ovb']['long'])],['Location coefficient × lead–location sorting',f(d['ovb']['product'])]],'Adding urban location to the simple regression')+
            formula(f"{f(d['ovb']['short'])} = {f(d['ovb']['long'])} + {f(d['ovb']['product'])}"),
            'The auxiliary regression uses urban location as its dependent variable and delivery time as its predictor. The product’s sign tells us which way the short-model slope shifts. These are deliberately nested models on the same 150 stores, so a sample change cannot explain the difference.')+
          teach('Categories need a reference group',bullets('With K categories and an intercept, include K−1 indicators.','Name the omitted reference category.','Interpret each coefficient relative to that category.','Keep coding rules aligned when predicting new rows.'),
            'For delivery categories 2, 3, 4, and 5 days, choose two days as the reference and create three indicators. A label such as urban=1 needs a documented meaning. Including every indicator with an intercept creates redundant columns rather than additional information.')+
          teach('An interaction makes a slope depend on context',formula('Rate = a + b × lead + c × urban + d × lead × urban'),
            'The lead-time slope is b for nonurban stores and b+d for urban stores. The urban difference at a particular delivery time is c+d×lead. For two continuous predictors, an interaction similarly lets the marginal association of one depend on the level of the other. Centring a predictor can make the reference point more useful.')+
          teach('Read fit and residuals together',bullets(f"Training R²: {f(d['r_squared'])}",f"Adjusted R²: {f(d['adjusted_r_squared'])}",'Inspect actual-versus-fitted values and residuals'),
            'Adjusted R² accounts for the number of fitted parameters when summarizing training fit. Neither statistic substitutes for new-data evaluation. In an actual-versus-fitted plot, state which variable is on which axis: with fitted on the horizontal axis, points above the diagonal have actual rates higher than predicted.')))
        before(c,'act',section('residual-review','Use unexpected performance to organize a practical review',
          teach('Find stores with more stockouts than their profile predicts',table(['Store','Actual rate','Fitted rate','Actual − fitted'],[[x['store_id'],f(x['baseline_rate']),f(x['predicted']),f(x['residual'])] for x in d['residuals']],'Largest positive residuals from the richer model'),
            'A residual shortlist asks a useful operational question: what is happening here that the recorded profile does not explain? Ask about delivery disruptions, local practices, and measurement. The model makes the comparison more specific; the next conversation supplies information the columns do not contain.')+
          ask('Turn a coefficient into a sentence','How would you explain the interaction result to a director who needs a store comparison?',
            'Name two store profiles, hold their other inputs fixed, calculate both fitted outcomes, and report the difference in percentage points. This is clearer than presenting the interaction coefficient without the main effects or the comparison level.')))
        c['appendix_extra']=section_html('multiple-regression-details','Matrix notation and interval targets',
          formula('β̂ = (XᵀX)⁻¹Xᵀy, when X has full column rank')+
          p('The implementation uses a least-squares solver rather than explicitly inverting XᵀX. HC1 robust covariance rescales the sandwich covariance by n/(n−k). A fitted mean at row x₀ has estimated variance x₀ᵀVar(β̂)x₀. A classical individual prediction interval additionally includes residual variance and assumes an appropriate model for that future variation.')+
          formula('OVB identity: β short − β long = γ omitted × δ sorting')+
          p('The identity is verified for the lead-only model, the lead-plus-location model, and the auxiliary location-on-lead regression. The broader six-column model then adds demand, promotions, and an interaction. The different specifications have different interpretation targets; their coefficients should not be compared without naming the held-fixed variables.'))
    return finish_expansion(n,c,r)

def section_html(key,title,body):
    return '<section id="'+esc(key)+'"><h2>'+esc(title)+'</h2>'+body+'</section>'

def finish_expansion(n,c,r):
    d=r['depth'];f=num
    if n==6:
        before(c,'read-data',section('prediction-task','Specify the output and the cost of a miss',
          teach('Define the task before choosing an algorithm',table(['Output needed','Prediction task','Retail use'],[
            ['A numerical stockout rate','Regression','Plan the expected review burden'],['A category such as above target','Classification','Choose which stores receive a review'],['A probability of missing the target','Probability estimation','Combine risk with the cost of action']],'The requested output determines the task'),
            'Name the prediction unit, target period, available inputs, and action. The course’s main target is a numerical rate for a store next week. A threshold can later turn that forecast into a queue, but the capacity rule and the accuracy measure remain separate choices.')+
          teach('Choose a loss that reflects the decision',formula('MAE = mean |actual − prediction|; MSE = mean (actual − prediction)²'),
            'RMSE is the square root of MSE. Squared loss gives especially large misses more influence. If missing a severe stockout problem is costlier than an unnecessary review, an asymmetric decision loss may be appropriate. State those costs before comparing models, and evaluate candidate procedures on the same observations.')+
          teach('Complexity changes both bias and variability',bullets('Underfitting: the model misses useful structure.','Overfitting: the model follows development-sample noise.','Irreducible variation: next week contains information unavailable today.'),
            'Expected prediction error is often discussed as squared bias, variance, and irreducible error. A more flexible model can reduce approximation bias while making the fitted procedure less stable. The purpose of validation is to observe the net effect on later, unused outcomes.')))
        before(c,'interpret',section('validation-design','Use repeated, time-ordered checks during development',
          teach('Move the validation window forward',table(['Training target weeks','Validation target weeks'],[[f"3–{x['train_end']}",f"{x['validation_start']}–{x['validation_end']}"] for x in d['folds']],'Rolling validation within development weeks 3–13'),
            'Ordinary k-fold validation fits on all but one fold and scores the held-out fold. For this weekly decision, preserve time instead: each validation window follows its training period. The final weeks 14–16 remain outside model tuning. Fit preprocessing, including scaling or imputation, using each fold’s training rows only.')+
          teach('Training criteria and validation answer different questions',table(['Model degree','Parameters','Training RMSE','AIC*','BIC*'],[[x['degree'],x['parameters'],f(x['training_rmse']),f(x['aic']),f(x['bic'])] for x in d['criteria']],'Same development rows; *common likelihood constants omitted'),
            'AIC and BIC penalize likelihood-based training fit for complexity. Here the Gaussian-error forms use n log(RSS/n) plus 2k or k log(n). They are comparable across these models because the outcome and observations are the same. Later-period prediction loss remains the direct check for the operating task.')+
          teach('Preprocessing belongs inside the fitted procedure',bullets('Define features from information available at the decision time.','Fit missing-value rules and scaling on training data.','Apply those rules unchanged to validation and test rows.','Keep target coding and category reference levels aligned.'),
            'A missing-value indicator can preserve information that a field was unavailable. An imputed value needs a stated rule; it is not a recovered observation. In this case the five forecast inputs are complete, so no imputation is needed. The important principle is that future observations must not influence the preparation of past training data.')))
        before(c,'act',section('lasso','Ask whether a smaller predictive model is useful',
          teach('LASSO adds a cost for large coefficients',formula('Minimize mean squared loss / 2 + α × Σ|slope coefficients|'),
            'As the penalty α increases, coefficients shrink and some become exactly zero. The intercept is not penalized. Standardize the candidate predictors so a coefficient’s penalty does not depend merely on whether its field is measured in days or index points. Retained coefficients describe this fitted prediction procedure, not causal importance.')+
          teach('Tune the penalty using development data',table(['Penalty α','Rolling validation RMSE'],[[x['alpha'],f(x['rmse'])] for x in d['tuning']],'Quadratic and interaction features; scaling refitted inside each fold'),
            f"The candidate features are the five timely inputs plus their degree-two terms and interactions. Rolling validation selects α={d['alpha']:g}. Refit that procedure on weeks 3–13, then evaluate it once on the final period. This extends the original regression-versus-tree exercise with a pre-specified regularized procedure.")+
          teach('Inspect the retained model and final error',bullets(f"LASSO retains {d['retained']} of {d['candidate_features']} candidate slope features",f"Final RMSE: {f(d['test_rmse'])} points; MAE: {f(d['test_mae'])}",f"Original selected procedure RMSE: {f(r['rmse'])} points")+
            table(['Retained standardized feature','Coefficient'],[[x['feature'],f(x['coefficient'])] for x in d['largest']],'Largest retained LASSO coefficients'),
            'This final comparison reports the performance of fixed procedures; it does not retune them using the test outcomes. When a small error difference competes with complexity, consider reproducibility, maintenance, and how often the model will be refitted.')+
          teach('A log prediction needs an explicit return to business units',formula(f"If predicted log Y = ln(10): exp(prediction) = 10; residual-adjusted mean = {f(d['log_example']['mean'])}"),
            'This arithmetic illustration uses log residuals −0.2 and +0.2. Exponentiating the mean log outcome does not generally give the mean outcome, because exponentiation is nonlinear. A residual smearing factor averages exp(residual). Compare transformed-target procedures using the same original-scale loss that matters for the decision, and establish how zeros are handled before taking logs.')+
          teach('Close the loop after deployment',bullets('Record the inputs, forecast, model version, and action taken.','Monitor prediction error and operating cost over time.','Check whether store conditions or data definitions have changed.','Set a review date and a rule for refitting or retiring the model.'),
            'A model trained on historical operations depends on a sufficiently stable relationship when deployed. New promotions, a changed monitoring basket, or the alert policy itself can change that relationship. Monitoring makes the forecast an operating process with an owner.')))
        c['appendix_extra']=section_html('prediction-details','Likelihood, penalties, and the tuning pipeline',
          p('Likelihood evaluates how a specified probability model supports the observed outcomes. Maximum likelihood chooses parameters that maximize it. For independent Gaussian errors with constant variance, the fitted mean coefficients coincide with OLS. For binary outcomes, logistic regression models probabilities and optimizes a different likelihood. Deviance compares log likelihood with a saturated reference model.')+
          formula('AIC = −2 log likelihood + 2k; BIC = −2 log likelihood + k log n')+
          code("model = make_pipeline(\n    PolynomialFeatures(2, include_bias=False),\n    StandardScaler(),\n    Lasso(alpha=0.01, max_iter=10000))\n# Fit this complete pipeline again inside every training fold.\nmodel.fit(training[features], training.stockout_rate)\nprediction = model.predict(validation[features])")+
          p('The executable source enumerates the four candidate penalties and the three expanding training windows. The scaling means and variances are estimated separately within each training fold. The saved result records all validation scores and the chosen penalty, so the final result can be traced to a specific selection rule.'))
    if n==7:
        before(c,'read-data',section('counterfactuals','Define exactly what “help” means',
          teach('Name the intervention, unit, and outcome',bullets('Unit: a store eligible for the pilot.','Treatment: an offer of replenishment alerts beginning in week 17.','Outcome: the store’s average stockout rate in weeks 17–24.','Contrast: usual operations versus the alert offer.'),
            'Predicting that a store will struggle is different from predicting how an alert changes its outcome. A causal question compares alternative interventions for the same unit at the same time. Define the offer precisely enough that another team could implement it.')+
          teach('Every store has two potential policy outcomes',formula('Y(0): usual-operation rate; Y(1): alert-offer rate; reduction = Y(0) − Y(1)'),
            'We use a positive reduction to mean improvement. A store reveals only the outcome under the policy it actually receives. The missing alternative is the counterfactual. This is the fundamental problem of causal inference: observing more detail about the factual outcome does not reveal the same store’s other policy path.')+
          teach('Different averages answer different spending questions',table(['Target','Whose reductions are averaged?'],[
            ['ATE','All stores in the named target population'],['ATT','Stores that receive the offer'],['ATU','Stores that do not receive it']],'Choose the target before calculating an effect')+
            formula('ATE = treated share × ATT + untreated share × ATU'),
            'Effects can vary across delivery times and locations, so these averages need not coincide. In this teaching world alerts reduce stockouts by different amounts across store types. In other businesses an intervention could also help some units and harm others; define the average without assuming identical responses.')+
          teach('Observed outcomes follow assignment',formula('Observed Y = (1 − D)Y(0) + DY(1), where D is the offer indicator'),
            'The observed usual-minus-offer group difference is directly calculable. In an observational comparison, it combines the treated group’s causal reduction with a baseline difference between the groups. Random assignment removes systematic selection in expectation, allowing the comparison to estimate the pilot population’s average effect.')))
        before(c,'calculate',section('experiment-design','Make the experiment interpretable before it starts',
          teach('Randomization is a procedure, not a table appearance',table(['Starting characteristic','Offered stores','Usual-operation stores'],[[x['variable'],f(x['offered']),f(x['usual'])] for x in d['balance']],'Pilot baseline balance'),
            'Record the eligibility list, random assignment, offer date, and exposure. Chance imbalances can remain in a particular draw; perfect equality is not required. Assignment records are stronger evidence of randomization than a collection of nonsignificant balance tests.')+
          teach('Keep the intervention and comparison stable',bullets('Define one operational version of the alert offer.','Track whether the offer is delivered and used.','Avoid spillovers between the assigned store groups.','Measure the same outcome and follow-up window in both groups.'),
            'Consistency links the named intervention to the potential outcome. No interference means one store’s assignment does not change another store’s outcome. Together with a well-defined treatment, these are often discussed under SUTVA. If stores share inventory or staff, design the assignment level to match those connections.')+
          teach('Controlled and natural experiments differ in who assigns',table(['Design','Source of variation'],[
            ['Controlled experiment','The research or operating team assigns the alternative policies.'],['Natural experiment','An external rule or event creates plausibly comparable exposure.']],'Find the source of the comparison'),
            'An external change is useful only when its assignment story supports the counterfactual comparison. A policy change alone does not guarantee comparability. The retail pilot uses explicit random offers; the later rollout has a different assignment process and will require a different analysis.')))
        before(c,'act',section('experiment-value','Connect the effect to a rollout rule',
          teach('An A/B comparison can also be written as regression',formula('Store outcome = intercept + offer coefficient × D + residual'),
            'With only an intercept and a binary offer, the fitted coefficient equals offered mean minus usual-operation mean. Its negative is our reported stockout reduction. Analyze the store-level follow-up means because assignment took place at the store level, even though each store supplies many product-days.')+
          teach('Use primary outcomes and guardrails together',bullets('Primary outcome: reduction in stockout rate.','Financial translation: stockout charge avoided minus alert cost.','Implementation records: delivery of alerts and staff review effort.','Guardrails: inventory and service problems elsewhere.'),
            'The case includes stockout counts and an explicit accounting cost rule. Staff effort and other operating guardrails are requirements for the next real implementation, not additional observed results in this dataset. Pre-specify the review horizon and replicate important findings in the next phase.')+
          teach('Use the known answer to check the reasoning','<details><summary>After making the pilot decision: reveal both paths</summary>'+outline([f"Realized ATE: {f(d['ate'])}; ATT: {f(d['att'])}; ATU: {f(d['atu'])} points",f"Observed group reduction = ATT + {f(d['selection_component'])} points",'Randomization balances selection across repetitions'],'answer')+p(f"Across the pilot’s realized potential outcomes: ATE = {f(d['ate'])}, ATT = {f(d['att'])}, ATU = {f(d['atu'])} points.",f"The observed group reduction equals ATT plus a selection component of {f(d['selection_component'])} points in this particular randomized draw. That finite-sample difference can occur by chance; the randomization argument concerns the assignment process across repetitions.")+'</details>',
            'The generated world lets us compare the actual assignment-based estimate with normally unobserved targets. Use this reveal to check the estimator after making the decision from the factual data.')))
        c['appendix_extra']=section_html('potential-outcomes','Inspect the time-machine table after the decision',
          table(['Store','Offer','Usual potential rate','Alert potential rate','Realized reduction'],[[x['store_id'],x['offer'],f(x['y0']),f(x['y1']),f(x['reduction'])] for x in d['potential_rows']],'Both generated paths, normally unobservable together')+
          formula('Observed reduction = ATT + {E[Y(0)|D=0] − E[Y(0)|D=1]}')+
          p('The selection component uses usual-operation potential outcomes for both groups. In actual observational data the treated group’s Y(0) is missing, which is why the decomposition is not a direct adjustment recipe. The known-answer table is generated for teaching and is separate from the public factual store-week table.'))
    if n==8:
        before(c,'read-data',section('identification','Turn the assignment story into an adjustment strategy',
          teach('Conditional independence is the working comparison claim',formula('(Y(0), Y(1)) independent of D, conditional on the chosen pre-policy variables X'),
            'The claim is that, among stores with the same relevant starting conditions, adoption does not carry further information about the potential outcomes. Positivity adds that both options are represented for the target profiles. Domain knowledge and the collection process supply this argument; a fitted model does not establish it automatically.')+
          teach('Subclassification makes the comparison visible',bullets('Define strata using pre-policy characteristics.','Compare adopters with nonadopters inside each stratum.','Calculate one effect estimate per stratum.','Weight the stratum estimates for the decision population.'),
            'The main example uses two delivery-time groups to expose the arithmetic. It is a first adjustment rather than a claim that delivery grouping captures every starting difference. The next lesson uses location and baseline performance as well.')))
        before(c,'interpret',section('graph-structures','Read the three basic causal-graph structures',
          teach('A chain carries part of the policy effect',diagram('Mediator: the action works through a mechanism',['Alert → earlier review → stockout rate']),
            'Earlier review is on the proposed causal pathway. Conditioning on it blocks that pathway, changing a total-effect question into a question about effects not transmitted through review. The intended effect determines whether that is the comparison we want.')+
          teach('A fork creates a backdoor comparison',diagram('Common cause: close the non-causal path',['Adoption ← delivery conditions → stockout rate']),
            'Delivery conditions can influence adoption and the outcome. Conditioning on the common cause blocks this path. A DAG—directed acyclic graph—expresses an assumed causal structure with arrows and no directed cycles. The arrows represent a business claim about the process, not correlations discovered by software.')+
          teach('A collider can create association when selected',diagram('Common consequence: selection can open a path',['Adoption → escalation to headquarters ← poor stockout performance']),
            'Suppose a store reaches a special review because it adopted the policy or because performance is poor. Restricting analysis to escalated stores links those two reasons for selection. The common consequence is a collider. Conditioning on it, or on information downstream from it, can open a path that was closed.')+
          teach('Follow a path before choosing a control',table(['Structure on the path','Without conditioning','Condition on the middle variable'],[
            ['Chain','Open','Blocked'],['Fork','Open','Blocked'],['Collider','Blocked','Opened']],'The three path rules'),
            'A path is blocked when it contains a conditioned non-collider or a collider whose node and descendants are not conditioned on. Two nodes are d-separated when every path between them is blocked. In a larger graph, inspect every path: blocking one backdoor route may leave another open.')+
          teach('Use the backdoor criterion for the total-effect question',bullets('Start with the intervention and outcome.','Find paths entering the intervention through an incoming arrow.','Block those non-causal paths with appropriate pre-treatment variables.','Keep the intervention’s causal pathways open.'),
            'For the standard backdoor adjustment set, avoid descendants of treatment and block each backdoor path. A mediator, collider, and confounder play different roles even if all three predict the outcome. More predictive controls do not necessarily create a better causal comparison.')+
          teach('A proxy carries information without revealing everything',diagram('Baseline performance can inform an unobserved capability',['Store capability → baseline performance','Store capability → later stockout rate']),
            'A baseline measure can help represent persistent store conditions. Measurement noise means that a proxy need not remove all confounding. In this case the adoption generator uses measured baseline performance, delivery time, and location; the technical source makes that specific assignment rule inspectable.')+
          ask('Choose a control by its role','Should the analyst adjust for review effort measured after stores receive alerts when estimating the total effect of offering alerts?',
            'Usually no: review effort is a possible mechanism of the offer’s effect. Use starting conditions to construct the total-effect comparison. A separate mediation question needs a separate target and additional assumptions.')))
        before(c,'act',section('target-weights','Give each stratum the weight of the intended population',
          teach('ATE, ATT, and ATU use different weights',table(['Delivery stratum','Reduction','All-store weight','Adopter weight','Nonadopter weight'],[[x['group'],f(x['reduction']),f(x['ate_weight']),f(x['att_weight']),f(x['atu_weight'])] for x in d['weights']],'The same stratum comparisons, three population mixes'),
            'The ATE weights sum to one across all stores; ATT weights follow the adopter mix; ATU weights follow the nonadopter mix. A different average can therefore result without changing a single within-stratum comparison.')+
          teach('Calculate all three weighted summaries',bullets(f"All-store estimate: {f(d['ate'])} points",f"Adopter-weighted estimate: {f(d['att'])} points",f"Nonadopter-weighted estimate: {f(d['atu'])} points"),
            'Name these as delivery-stratified estimates. The calculation teaches target weighting; it does not silently add adjustment for location and baseline performance. Matching is one way to make more detailed comparisons when a few broad strata are insufficient.')+
          teach('Use AI to draw an argument that people can inspect',bullets('Ask domain specialists why each arrow belongs.','Separate measured fields from latent causes and proposed mechanisms.','Mark the target effect and the proposed adjustment set.','Revise the graph when the operating story changes.'),
            'Software can draw a DAG and check d-separation implied by the supplied graph. It cannot establish causal direction from a neatly drawn diagram. Precision controls that predict only the outcome can help; variables that explain only treatment may add little outcome information and can worsen overlap.')))
        c['appendix_extra']=section_html('graph-details','Trace combined paths and their estimands',
          diagram('A fork plus a collider',['D ← X → Y','D → C ← Y','C → R'])+
          p('Conditioning on X blocks the common-cause path. Conditioning on C or its descendant R opens the collider route. These roles are path-specific: a node can be a collider on one path and a non-collider on another. The standard sufficient backdoor adjustment rule is useful for the total-effect target, but it is not a universal rule for every direct, mediated, or selected-population effect.')+
          formula('ATE = Σₓ effect(x)P(X=x); ATT = Σₓ effect(x)P(X=x|D=1); ATU = Σₓ effect(x)P(X=x|D=0)')+
          table(['Mechanism experiment','Control added','Known total reduction','Unadjusted','Adjusted'],[[x['mechanism'],x['control'],f(x['total_reduction']),f(x['naive']),f(x['adjusted'])] for x in d['simulations']],'Three numerical checks of the path rules')+
          p('These are separate, explicitly generated retail mechanism experiments with 3,000 store-scenarios each. They do not add observations to the 150-store operating history. The outcome is a continuous stockout-pressure index. A chain transmits the total effect through review effort; adjusting for it targets the remaining direct effect. A fork creates confounding removed by its pre-offer cause. Conditioning on the collider distorts an otherwise unconfounded comparison.')+
          code("# Chain experiment: total reduction is 2 * 1.5 = 3.\nrng = np.random.default_rng(SEED + 808)\noffer = rng.binomial(1, .5, 3000)\nreview = 1.5*offer + rng.normal(size=3000)\npressure = 20 - 2*review + rng.normal(size=3000)\nX = np.column_stack([np.ones(3000), offer, review])\nbeta, _, _ = fit_ols(X, pressure)")+
          p('The stored weights reproduce all three delivery-stratified estimates. No unrecorded demographic or operating variables are introduced into the case data. The chain and collider examples are explicit proposed mechanisms for this retail decision.'))
    if n==9:
        before(c,'read-data',section('ideal-experiment','Begin by specifying the experiment we would like to run',
          teach('Reconstruct the target trial in words',bullets('Eligibility: the 50 stores in the voluntary cohort.','Decision time: before adoption begins in week 17.','Options: offer alerts or continue usual operations.','Follow-up: weeks 17–24; outcome: average stockout rate.'),
            'Observational analysis is often necessary because management cannot randomize every policy. Specifying the ideal experiment clarifies which records, times, and variables belong in the comparison. The practical target is the effect for the stores covered by the proposed budget.')+
          teach('Identify why assignment may be endogenous',table(['Mechanism','Retail example'],[
            ['Common cause','Delivery problems affect adoption and future stockouts.'],['Reverse direction','Managers adopt because stockout pressure is already rising.'],['Measurement error','A noisy baseline fails to represent an important starting condition.']],'Three ways the observed comparison can be distorted'),
            'Externally assigned variation and voluntary choices can coexist. The assignment mechanism determines which comparisons are credible. Avoid adjusting for a mechanism after treatment or selecting on a common consequence; those choices can change or distort the target established in the preceding lesson.')+
          teach('Separate internal from external validity',bullets('Internal: does the comparison identify the effect for the study population?','External: how does that evidence apply to the stores targeted next?'),
            'A well-designed estimate can still need adaptation for a new population. Make sample restrictions, missing-data decisions, and coding choices explicit. Selecting stores with complete starting records or trimming extreme profiles changes the population whose effect is estimated.')))
        before(c,'act',section('matching-options','Compare adjustment tools using their actual retained stores',
          teach('Read progressively richer regressions on the same sample',table(['Specification','Reduction','95% model interval'],[[x['model'],f(x['reduction']),f(x['low'])+' to '+f(x['high'])] for x in d['models']],'Same voluntary cohort and follow-up outcome'),
            'The first model is the raw difference. The second adjusts for delivery time, location, and baseline rate with a constant offer coefficient. The third allows offer interactions and averages paired predictions across all target stores. Keep the sample fixed so that specification changes, rather than changing rows, explain differences.')+
          teach('Exact and coarsened matching make similarity explicit',table(['Method','Matched adopters','All adopters','Estimated reduction'],[[x['method'],x['matched_adopters'],x['total_adopters'],f(x['estimate'])] for x in d['matching']],'Matched-target estimates from alternative procedures'),
            'Exact matching here requires the same delivery time and location. Coarsened exact matching additionally puts baseline rates in five-point bands. Within a matched stratum, the comparison mean supplies an outcome for each adopter. Unmatched adopters are excluded, so the reported estimate concerns the retained adopter subset.')+
          teach('A propensity score models adoption, not the outcome',formula('Propensity score e(X) = P(adoption = 1 | pre-policy characteristics X)'),
            'The lab fits a regularized logistic model using delivery time, location, and baseline rate. It then finds a nearby nonadopter for each adopter on the logit of that score. A caliper of 0.2 times the score-logit standard deviation limits how far a match may be. Comparisons may be reused.')+
          teach('Inspect overlap before celebrating a match',table(['Group','Lowest fitted propensity','Highest fitted propensity'],[[x['group'],f(x['low']),f(x['high'])] for x in d['score_ranges']],'Fitted adoption-score support'),
            f"The caliper procedure uses {d['unique_comparisons']} distinct comparison stores. Similar scores can still conceal differences in individual covariates. Check the actual matches and report the number excluded; broad score ranges alone do not establish local overlap.")+
          teach('Check balance on the starting variables themselves',table(['Variable','Standardized difference before','After propensity matching'],[[x['variable'],f(x['before']),f(x['after'])] for x in d['balance']],'Adopter minus comparison; original pooled SD as denominator'),
            'A standardized mean difference divides the group mean difference by a common scale. The matched calculation weights comparison stores according to how often they are used. Inspect whether the relevant variables became more comparable; do not declare success from the propensity-model fit alone.')+
          ask('Name what the estimate covers','A stricter matching rule excludes several adopters. Can its effect still be presented as the effect for every adopter?',
            'No. Report the matched adopter population and its retained count. Compare its characteristics with the excluded stores. Extending the estimate to all adopters requires an additional argument, not just a different label.')))
        c['appendix_extra']=section_html('matching-details','Reproduce the matching choices',
          p('Nearest-neighbor covariate matching in the core calculation uses standardized squared distance with replacement. Exact matching and coarsened matching use stratum comparison means. Propensity matching uses a fitted logistic score, nearest neighbors on its logit, and the stated caliper. Distances within 1e-10 of the minimum are treated as numerical ties and resolved by the lowest store ID. These procedures can estimate different retained populations even when all are described as matching.')+
          formula('Standardized mean difference = (treated mean − comparison mean) / pooled pre-match SD')+
          p('The table does not attach a naive independent-observation interval to reused comparison records. Estimated scores, selection of matches, and reuse affect uncertainty. Inspect the saved match counts, balance measures, and regression specification before selecting a procedure for the decision.'))
    if n==10:
        before(c,'calculate',section('panel-design','Build the comparison before computing its effect',
          teach('The standard design has two groups and two periods',bullets('Adopters and comparison stores.','Before and after the rollout begins.','A stable store ID linking each period.','The same outcome definition in every cell.'),
            'A before-after change mixes the policy with the background change over time. DiD subtracts the comparison group’s change from the adopter group’s change. In this course we reverse that sign when reporting a positive stockout reduction.')+
          teach('Check the panel and define any weights',bullets(f"{d['balanced_stores']} stores observed before and after",f"{d['period_rows']} store-period averages",'Choose weights for the business target'),
            'A balanced panel observes each included store before and after. Investigate entry, exit, and missing periods before interpreting group changes. Equal store weights answer a store-average question. Exposure weights answer an opportunity-average question; because exposure is fixed here, those two weighting rules coincide.')+
          teach('Parallel trends defines the missing outcome path',formula('Without rollout, adopters would have changed by the same average amount as the comparison group.'),
            'The groups may have different baseline levels. DiD removes a fixed level difference and a common trend; it does not remove a separate shock that affects only the adopters at rollout. The target is the average effect on the selected adopters over the follow-up period.')))
        before(c,'act',section('did-regression','Recover the same contrast through regression',
          teach('The interaction coefficient is the signed DiD',formula('Y = a + b × adopter + c × after + d × adopter × after + error')+
            bullets(f"Interaction coefficient d: {f(d['regression'][3])}",f"Reported reduction −d: {f(d['regression_reduction'])} points"),
            'The intercept describes comparison stores before rollout. The adopter coefficient describes the initial group gap. The after coefficient describes the comparison trend. The interaction adds the adopter-specific change. The four-mean calculation and this regression agree exactly on the same equally weighted data.')+
          teach('Use a pre-period placebo as a diagnostic',bullets('Compare weeks 17–20 with weeks 21–24',f"Placebo reduction: {f(d['placebo']['value'])} points",f"95% interval: {f(d['placebo']['low'])}–{f(d['placebo']['high'])} points"),
            'The main graph shows the weekly path before and after the offer. A pre-period comparison can reveal obvious divergence and help judge an operating story. A small or imprecise placebo estimate does not prove the unobserved post-period counterfactual; combine the diagnostic with knowledge of contemporaneous changes.')+
          teach('Allow baseline characteristics to explain different changes',bullets('Adjust changes for baseline rate, delivery time, and location',f"Adjusted reduction: {f(d['controlled']['value'])} points",f"95% interval: {f(d['controlled']['low'])}–{f(d['controlled']['high'])} points"),
            'This model uses pre-policy characteristics, not variables caused by the rollout. It asks whether the group comparison changes when stores with different starting conditions may follow different trends. Report the specification alongside the unadjusted DiD rather than selecting the result that looks most favorable.')+
          teach('Keep subgroup evidence attached to its sample',table(['Location','Adopters','Comparisons','Reduction','95% interval'],[['Urban' if x['urban'] else 'Other',x['adopters'],x['comparison'],f(x['value']),f(x['low'])+' to '+f(x['high'])] for x in d['subgroups']],'Separate rollout comparisons by location'),
            'A subgroup comparison answers a more specific expansion question and uses fewer stores. Compare the group sizes and uncertainty as well as the point estimates. A significant estimate in one group and an insignificant estimate in another is not itself a test that the effects differ.')+
          teach('Changing weights changes the business target',bullets('Give long-lead stores twice the planning weight',f"Weighted reduction: {f(d['priority_weighted'])} points",'State the priority rule beside the result'),
            'These are explicit priority weights for a sensitivity exercise, not observed sales or customer counts. Weighted least squares on the same two-period data gives the corresponding weighted contrast. Name the weighting rule and target whenever a weighted average replaces the equal-store result.')+
          teach('Continuous exposure requires a defined dose',formula('Y = a + unit terms + time terms + b × baseline exposure × after + error'),
            'A continuous-treatment design could compare changes by a pre-defined exposure measure. The coefficient then describes a change per unit of exposure rather than a binary offer effect. This course’s rollout is binary; no continuous-dose estimate is claimed for unrecorded alert intensity.')+
          ask('Complete the expansion recommendation','What should accompany the final DiD number in the director’s decision memo?',
            'Name the selected adopter stores, the comparison group, the before and after windows, the rate definition, the parallel-trend argument, the uncertainty, and the accounting rule. Then specify the next rollout action and the information that could change it.')))
        c['appendix_extra']=section_html('did-details','Connect first differences, weights, and uncertainty',
          formula('Changeᵢ = a + b × adopterᵢ + errorᵢ; reported reduction = −b')+
          p('The core interval compares independent store-level changes using Welch’s formula, preserving the store as the independent unit. The controlled change regression uses HC1 covariance. Repeating a store’s eight weekly observations does not create eight independently assigned stores. A full weekly-panel specification should account for within-store dependence.')+
          p('The two-period interaction regression reproduces the point estimate. Baseline controls in a first-difference model permit trend differences associated with starting conditions. With more periods or different adoption dates, the design and interpretation require additional choices; the present exercise has one common rollout date.'))
    from curriculum_worked import WORKED
    if n in WORKED:c['code']+='\n\n'+WORKED[n]+'\n'
    return c
